$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$root = (Get-Location).Path
$packagePath = Join-Path $root "package.json"
$cnApplicationsPath = Join-Path $root "app\applications"
$intlApplicationsPath = Join-Path $root "app\[locale]\applications"

foreach ($requiredPath in @(
  $packagePath,
  $cnApplicationsPath,
  $intlApplicationsPath
)) {
  if (-not (Test-Path -LiteralPath $requiredPath)) {
    throw "没有找到必要路径：$requiredPath"
  }
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupMap = @{}
$createdFiles = New-Object System.Collections.Generic.List[string]

function Backup-File {
  param([string]$Path)

  if (-not (Test-Path -LiteralPath $Path)) {
    return
  }

  if ($script:backupMap.ContainsKey($Path)) {
    return
  }

  $backupPath = $Path + "." + $stamp + ".bak"
  Copy-Item -LiteralPath $Path -Destination $backupPath -Force
  $script:backupMap[$Path] = $backupPath

  Write-Host "已备份：$backupPath" -ForegroundColor Yellow
}

function Write-Utf8NoBom {
  param(
    [string]$Path,
    [string]$Content
  )

  $directory = Split-Path -Parent $Path

  if (-not (Test-Path -LiteralPath $directory)) {
    New-Item -ItemType Directory -Path $directory -Force | Out-Null
  }

  if (Test-Path -LiteralPath $Path) {
    Backup-File -Path $Path
  }
  else {
    $script:createdFiles.Add($Path)
  }

  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}

function Decode-Base64Utf8 {
  param([string]$Encoded)

  $bytes = [System.Convert]::FromBase64String($Encoded)
  return [System.Text.Encoding]::UTF8.GetString($bytes)
}

function Update-ApplicationPageFallback {
  param([string]$Path)

  $content = Get-Content -LiteralPath $Path -Raw -Encoding UTF8

  if ($content -notmatch 'fallback=\{\s*null\s*\}') {
    return
  }

  Backup-File -Path $Path

  if ($content -notmatch 'import\s+ApplicationPageSkeleton\s+from\s+["'']@/components/common/ApplicationPageSkeleton["'']') {
    $firstImportIndex = $content.IndexOf("import ")

    if ($firstImportIndex -lt 0) {
      throw "无法在页面中找到 import 插入位置：$Path"
    }

    $skeletonImport = 'import ApplicationPageSkeleton from "@/components/common/ApplicationPageSkeleton";'
    $content = $content.Insert(
      $firstImportIndex,
      $skeletonImport + [Environment]::NewLine
    )
  }

  $content = [Regex]::Replace(
    $content,
    'fallback=\{\s*null\s*\}',
    'fallback={<ApplicationPageSkeleton />}'
  )

  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $content, $encoding)

  Write-Host "已更新骨架 fallback：$Path" -ForegroundColor Green
}

try {

  $contentBase641 = @'

'@

  $content1 = Decode-Base64Utf8 -Encoded ($contentBase641.Trim())
  Write-Utf8NoBom -Path (Join-Path $root "components\common\ApplicationPageSkeleton.tsx") -Content $content1

  $contentBase642 = @'

'@

  $content2 = Decode-Base64Utf8 -Encoded ($contentBase642.Trim())
  Write-Utf8NoBom -Path (Join-Path $root "components\common\ApplicationPageSkeleton.module.css") -Content $content2

  $contentBase643 = @'
aW1wb3J0IEFwcGxpY2F0aW9uUGFnZVNrZWxldG9uIGZyb20gIkAvY29tcG9uZW50cy9jb21tb24vQXBwbGljYXRpb25QYWdlU2tlbGV0b24iOwoKZXhwb3J0IGRlZmF1bHQgZnVuY3Rpb24gQXBwbGljYXRpb25zTG9hZGluZygpIHsKICByZXR1cm4gPEFwcGxpY2F0aW9uUGFnZVNrZWxldG9uIC8+Owp9Cg==
'@

  $content3 = Decode-Base64Utf8 -Encoded ($contentBase643.Trim())
  Write-Utf8NoBom -Path (Join-Path $root "app\applications\loading.tsx") -Content $content3

  $contentBase644 = @'
aW1wb3J0IEFwcGxpY2F0aW9uUGFnZVNrZWxldG9uIGZyb20gIkAvY29tcG9uZW50cy9jb21tb24vQXBwbGljYXRpb25QYWdlU2tlbGV0b24iOwoKZXhwb3J0IGRlZmF1bHQgZnVuY3Rpb24gTG9jYWxpemVkQXBwbGljYXRpb25zTG9hZGluZygpIHsKICByZXR1cm4gPEFwcGxpY2F0aW9uUGFnZVNrZWxldG9uIC8+Owp9Cg==
'@

  $content4 = Decode-Base64Utf8 -Encoded ($contentBase644.Trim())
  Write-Utf8NoBom -Path (Join-Path $root "app\[locale]\applications\loading.tsx") -Content $content4

  $applicationPages = New-Object System.Collections.Generic.List[string]

  Get-ChildItem -LiteralPath $cnApplicationsPath -Recurse -File -Filter "page.tsx" |
    ForEach-Object {
      $applicationPages.Add($_.FullName)
    }

  Get-ChildItem -LiteralPath $intlApplicationsPath -Recurse -File -Filter "page.tsx" |
    ForEach-Object {
      $applicationPages.Add($_.FullName)
    }

  foreach ($pagePath in $applicationPages) {
    Update-ApplicationPageFallback -Path $pagePath
  }

  $nextPath = Join-Path $root ".next"

  if (Test-Path -LiteralPath $nextPath) {
    Remove-Item -LiteralPath $nextPath -Recurse -Force
    Write-Host "已清理 .next 缓存。" -ForegroundColor Yellow
  }

  Write-Host ""
  Write-Host "正在运行 npm run build……" -ForegroundColor Cyan

  & npm run build

  if ($LASTEXITCODE -ne 0) {
    throw "构建失败。"
  }

  Write-Host ""
  Write-Host "执行完成：" -ForegroundColor Green
  Write-Host " - 中文应用领域页面已加入统一骨架"
  Write-Host " - 多语言应用领域页面已加入统一骨架"
  Write-Host " - 所有 fallback={null} 已替换为应用页面骨架"
  Write-Host " - Banner、导航、介绍、卡片区域会先占位"
  Write-Host " - Footer 不会在正文加载前提前顶上来"
  Write-Host " - npm run build 已通过"
}
catch {
  Write-Host ""
  Write-Host "执行失败：$($_.Exception.Message)" -ForegroundColor Red
  Write-Host "正在恢复本次修改……" -ForegroundColor Yellow

  foreach ($path in $backupMap.Keys) {
    $backupPath = $backupMap[$path]

    if (Test-Path -LiteralPath $backupPath) {
      Copy-Item -LiteralPath $backupPath -Destination $path -Force
    }
  }

  foreach ($createdFile in $createdFiles) {
    if (Test-Path -LiteralPath $createdFile) {
      Remove-Item -LiteralPath $createdFile -Force
    }
  }

  Write-Host "本次修改已恢复。" -ForegroundColor Yellow
  throw
}
